local P,RS,W,CAM,LP,CG,UIS,VIM,TS,HS,ST = game:GetService("Players"),game:GetService("RunService"),game:GetService("Workspace"),game:GetService("Workspace").CurrentCamera,game:GetService("Players").LocalPlayer,game:GetService("CoreGui"),game:GetService("UserInputService"),game:GetService("VirtualInputManager"),game:GetService("TweenService"),game:GetService("HttpService"),game:GetService("Stats")
local S=_G.ESP_CONFIG
local function mk(cl,pr,pa) local o=Instance.new(cl) for k,v in pairs(pr or {}) do pcall(function() o[k]=v end) end if pa then pcall(function() o.Parent=pa end) end return o end
if CG:FindFirstChild("ESP_GUI") then CG.ESP_GUI:Destroy() end
local gui=mk("ScreenGui",{Name="ESP_GUI",ResetOnSpawn=false,IgnoreGuiInset=true,DisplayOrder=999}) pcall(function() gui.Parent=CG end)
local wm=mk("Frame",{Size=UDim2.new(0,200,0,26),Position=UDim2.new(1,-220,0,20),BackgroundColor3=Color3.fromRGB(25,25,30),BackgroundTransparency=0.2,Parent=gui}) mk("UICorner",{CornerRadius=UDim.new(0,6)},wm) mk("UIStroke",{Color=Color3.fromRGB(0,255,0),Thickness=1},wm) local wmT=mk("TextLabel",{Size=UDim2.new(1,0,1,0),BackgroundTransparency=1,Text="FPS: -- | Ping: --",TextColor3=Color3.fromRGB(255,255,255),Font=Enum.Font.GothamBold,TextSize=12,Parent=wm})
_G.UPDATE_HUD = function(fps,ping) wmT.Text=string.format("FPS: %d | Ping: %dms",fps,ping) end
local main=mk("Frame",{Size=UDim2.new(0,300,0,520),Position=UDim2.new(0,20,0,80),BackgroundColor3=Color3.fromRGB(25,25,30),BorderSizePixel=0,Active=true,Parent=gui}) mk("UICorner",{CornerRadius=UDim.new(0,8)},main) mk("UIStroke",{Color=Color3.fromRGB(60,60,70),Thickness=1},main)
local hdr=mk("Frame",{Size=UDim2.new(1,0,0,32),BackgroundColor3=Color3.fromRGB(35,35,42),BorderSizePixel=0,Parent=main}) mk("UICorner",{CornerRadius=UDim.new(0,8)},hdr) mk("TextLabel",{Size=UDim2.new(1,-100,1,0),Position=UDim2.new(0,12,0,0),BackgroundTransparency=1,Text="ESP v10.0",TextColor3=Color3.fromRGB(230,230,230),Font=Enum.Font.GothamBold,TextSize=14,TextXAlignment=Enum.TextXAlignment.Left,Parent=hdr})
local iconBtn
mk("TextButton",{Size=UDim2.new(0,26,0,26),Position=UDim2.new(1,-30,0,3),BackgroundTransparency=1,Text="✕",TextColor3=Color3.fromRGB(255,120,120),Font=Enum.Font.GothamBold,TextSize=14,Parent=hdr}).MouseButton1Click:Connect(function() TS:Create(main,TweenInfo.new(0.2,Enum.EasingStyle.Back,Enum.EasingDirection.In),{Size=UDim2.new(0,0,0,0)}):Play() task.wait(0.2) main.Visible=false iconBtn.Visible=true end)
iconBtn=mk("TextButton",{Name="MinIcon",Size=UDim2.new(0,50,0,50),Position=UDim2.new(0,50,0,50),BackgroundColor3=Color3.fromRGB(25,25,30),Text="ESP",TextColor3=Color3.fromRGB(255,255,255),Font=Enum.Font.GothamBold,TextSize=12,BorderSizePixel=0,Visible=false,Parent=gui}) mk("UICorner",{CornerRadius=UDim.new(1,0)},iconBtn) mk("UIStroke",{Color=Color3.fromRGB(0,255,0),Thickness=2},iconBtn)
iconBtn.MouseButton1Click:Connect(function() iconBtn.Visible=false main.Visible=true TS:Create(main,TweenInfo.new(0.2,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{Size=UDim2.new(0,300,0,520)}):Play() end)
local drag,ds,ss hdr.InputBegan:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 then drag=true ds=i.Position ss=main.Position end end)
UIS.InputChanged:Connect(function(i) if drag and i.UserInputType==Enum.UserInputType.MouseMovement then local d=i.Position-ds main.Position=UDim2.new(ss.X.Scale,ss.X.Offset+d.X,ss.Y.Scale,ss.Y.Offset+d.Y) end end)
UIS.InputEnded:Connect(function(i) if i.UserInputType==Enum.UserInputType.MouseButton1 then drag=false end end)
local scr=mk("ScrollingFrame",{Size=UDim2.new(1,-16,1,-80),Position=UDim2.new(0,8,0,40),BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=4,AutomaticCanvasSize=Enum.AutomaticSize.Y,Parent=main}) mk("UIListLayout",{Padding=UDim.new(0,6),SortOrder=Enum.SortOrder.LayoutOrder},scr)
local ord=0 local function nO() ord+=1 return ord end
local tbSt=mk("Frame",{Size=UDim2.new(0,140,0,26),Position=UDim2.new(0.5,-70,0,10),BackgroundColor3=Color3.fromRGB(180,40,40),BackgroundTransparency=0.5,Parent=gui}) mk("UICorner",{CornerRadius=UDim.new(0,6)},tbSt) local tbStr=mk("UIStroke",{Color=Color3.fromRGB(255,0,0),Thickness=1},tbSt) local tbT=mk("TextLabel",{Size=UDim2.new(1,0,1,0),BackgroundTransparency=1,Text="TRIGGERBOT: OFF",TextColor3=Color3.new(1,1,1),Font=Enum.Font.GothamBold,TextSize=12,Parent=tbSt})
_G.UPDATE_TB = function(on) if on then tbSt.BackgroundColor3=Color3.fromRGB(0,180,60) tbStr.Color=Color3.fromRGB(0,255,0) tbT.Text="TRIGGERBOT: ON" else tbSt.BackgroundColor3=Color3.fromRGB(180,40,40) tbStr.Color=Color3.fromRGB(255,0,0) tbT.Text="TRIGGERBOT: OFF" end end
_G.SHOW_TOAST = function(t) local toast=mk("TextLabel",{Size=UDim2.new(0,300,0,40),Position=UDim2.new(0.5,-150,0.6,0),BackgroundTransparency=1,Text=t,TextColor3=Color3.fromRGB(255,255,255),Font=Enum.Font.GothamBold,TextSize=24,TextStrokeTransparency=0,Parent=gui}) TS:Create(toast,TweenInfo.new(0.5,Enum.EasingStyle.Back),{Position=UDim2.new(0.5,-150,0.55,0)}):Play() task.delay(1.5,function() if toast then TS:Create(toast,TweenInfo.new(0.5),{TextTransparency=1}):Play() task.wait(0.5) toast:Destroy() end end) end
local function addTg(txt,def,cb) local row=mk("Frame",{Size=UDim2.new(1,0,0,24),BackgroundTransparency=1,LayoutOrder=nO(),Parent=scr}) local b=mk("TextButton",{Size=UDim2.new(0,16,0,16),Position=UDim2.new(0,4,0.5,-8),BackgroundColor3=def and Color3.fromRGB(0,200,100) or Color3.fromRGB(60,60,70),Text="",BorderSizePixel=0,AutoButtonColor=false,Parent=row}) mk("UICorner",{CornerRadius=UDim.new(0,4)},b) mk("TextLabel",{Size=UDim2.new(1,-30,1,0),Position=UDim2.new(0,28,0,0),BackgroundTransparency=1,Text=txt,TextColor3=Color3.fromRGB(220,220,220),Font=Enum.Font.Gotham,TextSize=12,TextXAlignment=Enum.TextXAlignment.Left,Parent=row}) local st=def b.MouseButton1Click:Connect(function() st=not st b.BackgroundColor3=st and Color3.fromRGB(0,200,100) or Color3.fromRGB(60,60,70) cb(st) end) end
local function addSep(txt) local row=mk("Frame",{Size=UDim2.new(1,0,0,20),BackgroundTransparency=1,LayoutOrder=nO(),Parent=scr}) mk("TextLabel",{Size=UDim2.new(1,-8,1,0),BackgroundTransparency=1,Text="── "..txt.." ──",TextColor3=Color3.fromRGB(120,140,170),Font=Enum.Font.GothamBold,TextSize=11,TextXAlignment=Enum.TextXAlignment.Left,Parent=row}) end
addSep("ESP") addTg("ESP вкл",S.Enabled,function(v) S.Enabled=v end) addTg("Бокс",S.ShowBox,function(v) S.ShowBox=v end) addTg("Имя",S.ShowName,function(v) S.ShowName=v end) addTg("Дистанция",S.ShowDistance,function(v) S.ShowDistance=v end) addTg("HP",S.ShowHealth,function(v) S.ShowHealth=v end) addTg("Скелет",S.ShowSkeleton,function(v) S.ShowSkeleton=v end)
addSep("AIMBOT") local abTg=mk("TextButton",{Size=UDim2.new(1,-8,0,26),BackgroundColor3=Color3.fromRGB(60,60,80),Text="AIMBOT: OFF",TextColor3=Color3.fromRGB(255,255,255),Font=Enum.Font.GothamBold,TextSize=12,BorderSizePixel=0,Parent=scr,LayoutOrder=nO()}) mk("UICorner",{CornerRadius=UDim.new(0,4)},abTg) abTg.MouseButton1Click:Connect(function() S.AB_Enabled=not S.AB_Enabled abTg.BackgroundColor3=S.AB_Enabled and Color3.fromRGB(0,180,60) or Color3.fromRGB(60,60,80) abTg.Text=S.AB_Enabled and "AIMBOT: ON" or "AIMBOT: OFF" _G.SHOW_TOAST(S.AB_Enabled and "Aimbot ON" or "Aimbot OFF") end)
addSep("TRIGGERBOT") local tbTg=mk("TextButton",{Size=UDim2.new(1,-8,0,26),BackgroundColor3=Color3.fromRGB(60,60,80),Text="TRIGGERBOT: OFF",TextColor3=Color3.fromRGB(255,255,255),Font=Enum.Font.GothamBold,TextSize=12,BorderSizePixel=0,Parent=scr,LayoutOrder=nO()}) mk("UICorner",{CornerRadius=UDim.new(0,4)},tbTg) tbTg.MouseButton1Click:Connect(function() S.TB_Enabled=not S.TB_Enabled tbTg.BackgroundColor3=S.TB_Enabled and Color3.fromRGB(0,180,60) or Color3.fromRGB(60,60,80) tbTg.Text=S.TB_Enabled and "TRIGGERBOT: ON" or "TRIGGERBOT: OFF" _G.UPDATE_TB(S.TB_Enabled) _G.SHOW_TOAST(S.TB_Enabled and "TriggerBot ON" or "TriggerBot OFF") end)
mk("TextButton",{Size=UDim2.new(1,-16,0,26),Position=UDim2.new(0,8,1,-34),BackgroundColor3=Color3.fromRGB(180,40,40),Text="Выгрузить",TextColor3=Color3.fromRGB(255,255,255),Font=Enum.Font.GothamBold,TextSize=12,Parent=main}).MouseButton1Click:Connect(function() gui:Destroy() end)
